package main

import (
	"database/sql"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"os"
	"strconv"
	"sort"
)

type Connection struct {
	TargetNode string `json:"target_node"`
	Weight     int    `json:"weight"`
}

type SourceNode struct {
	SourceNode        string       `json:"source_node"`
	TotalInteractions int          `json:"total_interactions"`
	Connections       []Connection `json:"connections"`
}

type Edge struct {
	Source           string
	Target           string
	InteractionCount int
}

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: go run build_graph.go <threshold>")
		os.Exit(1)
	}
	threshold, err := strconv.Atoi(os.Args[1])
	if err != nil {
		log.Fatalf("Invalid threshold: %v", err)
	}

	csvPath := "/home/user/analytics/network.csv"
	outputPath := "/home/user/analytics/output.json"

	csvFile, err := os.Open(csvPath)
	if err != nil {
		log.Fatal(err)
	}
	defer csvFile.Close()

	reader := csv.NewReader(csvFile)
	var allEdges []Edge
	sourceTotals := make(map[string]int)

	for {
		record, err := reader.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			log.Fatal(err)
		}
		count, _ := strconv.Atoi(record[2])
		allEdges = append(allEdges, Edge{
			Source:           record[0],
			Target:           record[1],
			InteractionCount: count,
		})
		sourceTotals[record[0]] += count
	}

	var qualifyingSources []string
	for source, total := range sourceTotals {
		if total > threshold {
			qualifyingSources = append(qualifyingSources, source)
		}
	}
	sort.Strings(qualifyingSources)

	var result []SourceNode
	for _, source := range qualifyingSources {
		sn := SourceNode{
			SourceNode:        source,
			TotalInteractions: sourceTotals[source],
			Connections:       []Connection{},
		}

		for _, edge := range allEdges {
			if edge.Source == source {
				sn.Connections = append(sn.Connections, Connection{
					TargetNode: edge.Target,
					Weight:     edge.InteractionCount,
				})
			}
		}

		sort.Slice(sn.Connections, func(i, j int) bool {
			return sn.Connections[i].TargetNode < sn.Connections[j].TargetNode
		})

		result = append(result, sn)
	}

	outputFile, err := os.Create(outputPath)
	if err != nil {
		log.Fatal(err)
	}
	defer outputFile.Close()

	encoder := json.NewEncoder(outputFile)
	encoder.SetIndent("", "  ")
	err = encoder.Encode(result)
	if err != nil {
		log.Fatal(err)
	}
}
EOF
"}

